import XCTest

final class BlueskyUITap: XCTestCase {
    func testOpenMessages() {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()

        // Accept the system confirmation for the Bluesky custom URL if it is still shown.
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let openButton = springboard.alerts.buttons["Open"]
        if openButton.waitForExistence(timeout: 2) {
            openButton.tap()
        } else {
            // Coordinate fallback for the system confirmation sheet.
            app.coordinate(withNormalizedOffset: CGVector(dx: 0.67, dy: 0.55)).tap()
        }

        // Let the deep link settle, then select the bottom-bar Chat tab.
        Thread.sleep(forTimeInterval: 2)
        app.coordinate(withNormalizedOffset: CGVector(dx: 0.50, dy: 0.935)).tap()
        Thread.sleep(forTimeInterval: 2)
    }
}
EOF
